// The crafted DotNetCorePathFinderExtensions manifests and the gold dump
// of the REAL installed ICSharpCode.Decompiler 11.0 drives over the real
// local assemblies, these manifests, and the synthetic-path matrix (built by
// the C:/temp-probe/DtfProbe probe; regenerate the hex together with the
// gold -- the ManagedPEBuilder TimeDateStamp makes each build unique).
// One manifest per DetectTargetFrameworkId arm no real assembly carries:
// the attribute walk (a skipped [Foo] row, the space-stripped form, the
// SerString null, the wrong prolog, the malformed blob, the nil Value
// handle), the assembly-name arm (mscorlib / netstandard / System.Runtime
// across the whole GetDotNetCoreVersion matrix / System.Private.CoreLib),
// the AssemblyReference passes (mscorlib / System.Runtime / the nil-key
// skips), [ReferenceAssembly], and the DetectRuntimePack name matrix (the
// case-sensitive StringComparer hit/miss and the nil-key skip).

