// Writes one of the crafted manifests to a temp file and returns the path.
inline std::string WriteDtfDll(const char* tag, const std::uint8_t* bytes,
                               std::size_t size)
{
    namespace fs = std::filesystem;
    fs::path path = fs::temp_directory_path()
        / ("ilspy_dtf_" + std::string(tag) + ".dll");
    std::FILE* out = std::fopen(path.string().c_str(), "wb");
    if (out == nullptr)
        throw std::runtime_error("cannot write the DTF manifest");
    std::fwrite(bytes, 1, size, out);
    std::fclose(out);
    return path.string();
}

